import{_ as s,o as e,c as t,ae as n}from"./chunks/framework.BX6FPmO9.js";const m=JSON.parse('{"title":"Mock Dataset 版本化","description":"","frontmatter":{},"headers":[],"relativePath":"conventions/mock-dataset-versioning.md","filePath":"conventions/mock-dataset-versioning.md"}'),o={name:"conventions/mock-dataset-versioning.md"};function r(i,a,l,c,d,p){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="mock-dataset-版本化" tabindex="-1">Mock Dataset 版本化 <a class="header-anchor" href="#mock-dataset-版本化" aria-label="Permalink to &quot;Mock Dataset 版本化&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>Mock 情境以 <strong>dataset version</strong> 管理，對應資料治理中的「可回溯、可重現、可控變更」（類 Delta time travel 精神）。</p><hr><h2 id="目錄約定" tabindex="-1">目錄約定 <a class="header-anchor" href="#目錄約定" aria-label="Permalink to &quot;目錄約定&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app/test/</span></span>
<span class="line"><span>  datasets/</span></span>
<span class="line"><span>    v1/                    # 第一版 mock 情境</span></span>
<span class="line"><span>      items.json          # 可選：fixture 從檔案讀</span></span>
<span class="line"><span>      README.md            # 說明此版對應的 schema / 功能</span></span>
<span class="line"><span>    v2/                    # schema 或情境變更後的新版</span></span>
<span class="line"><span>      items.json</span></span>
<span class="line"><span>      MIGRATION.md         # 從 v1 的變更說明、breaking 欄位</span></span>
<span class="line"><span>  handlers.ts              # 可依環境或參數選用 v1/v2 fixture</span></span>
<span class="line"><span>  fixtures/                # 現有寫在程式內的 fixture 可逐步遷到 datasets/vN</span></span></code></pre></div><ul><li><strong>v1, v2, …</strong>：依功能或 schema 變更新增版本，不直接覆寫舊版。</li><li><strong>MIGRATION.md</strong>：該版相對於前一版的變更、breaking changes、欄位語意變更。</li></ul><hr><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><ol><li><strong>Handler</strong>：可從 <code>datasets/v1/</code> 或 <code>datasets/v2/</code> 讀取 fixture（或由常數 <code>CURRENT_DATASET_VERSION</code> / 環境變數決定），再經契約 schema parse 後回傳。</li><li><strong>測試</strong>：單元／整合測試可指定 <code>process.env.MSW_DATASET_VERSION=v1</code> 等，使結果可重現。</li><li><strong>新功能改 schema</strong>：新增 <code>datasets/v2/</code>，在 v2 放新 fixture，並在 <code>MIGRATION.md</code> 註明與 v1 的差異；舊測試仍可選 v1。</li></ol><hr><h2 id="與契約的關係" tabindex="-1">與契約的關係 <a class="header-anchor" href="#與契約的關係" aria-label="Permalink to &quot;與契約的關係&quot;">​</a></h2><ul><li>每個 dataset 版本內的 fixture 仍須通過<strong>當前契約 schema</strong> parse（或該版本對應的 schema，若專案支援多版 schema）。</li><li>若 schema 與 dataset 一起版本化，可在 <code>datasets/v2/</code> 註明「對應 contracts 的某某 tag 或日期」。</li></ul><hr><h2 id="相關" tabindex="-1">相關 <a class="header-anchor" href="#相關" aria-label="Permalink to &quot;相關&quot;">​</a></h2><ul><li><a href="./../architecture/data-governance.html">data-governance</a>：為何要做 dataset 版本化、與 Delta 精神的對應</li><li><a href="./../product/mock-data.html">mock-data</a>：整體 mock 策略</li><li><a href="./data-test-driven.html">data-test-driven</a>：Handler 須經 schema parse</li></ul>`,16)])])}const v=s(o,[["render",r]]);export{m as __pageData,v as default};
